#include <zephyr/ztest.h>
#include <zephyr/modem/modem_backend_tty.h>
#include <zephyr/kernel.h>
#include <zephyr/drivers/uart.h>
#include <string.h>

#define LOG_LEVEL CONFIG_MODEM_BACKEND_TTY_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(modem_backend_tty_test);

/* Mock UART device */
static K_FIFO_DEFINE(mock_uart_rx_fifo);
static K_SEM_DEFINE(mock_uart_tx_sem, 0, 1);

static int mock_uart_fifo_read(const struct device *dev, uint8_t *buf, size_t len)
{
    ARG_UNUSED(dev);
    size_t bytes_read = 0;
    while (bytes_read < len) {
        struct k_fifo_buf *item = k_fifo_get(&mock_uart_rx_fifo, K_NO_WAIT);
        if (!item) {
            break;
        }
        *buf++ = *(uint8_t *)item->data;
        k_fifo_buf_put(&mock_uart_rx_fifo, item); /* Return buffer to pool */
        bytes_read++;
    }
    return bytes_read;
}

static int mock_uart_fifo_write(const struct device *dev, const uint8_t *buf, size_t len)
{
    ARG_UNUSED(dev);
    /* In a real scenario, this would put data into a TX buffer.
     * For this test, we just signal TX completion.
     */
    k_sem_give(&mock_uart_tx_sem);
    return len;
}

static const struct uart_driver_api mock_uart_api = {
    .fifo_read = mock_uart_fifo_read,
    .fifo_write = mock_uart_fifo_write,
};

static struct device mock_uart_dev = {
    .api = &mock_uart_api,
    .name = "mock_uart",
};

/* Modem backend TTY instance */
static struct modem_backend_tty tty_backend;
static K_EVENT_DEFINE(tty_events);
static K_FIFO_DEFINE(tty_rx_fifo);
static K_SEM_DEFINE(tty_tx_sem, 0, 1);

static const struct modem_backend_tty_config tty_config = {
    .uart_dev = &mock_uart_dev,
    .rx_fifo = &tty_rx_fifo,
    .tx_sem = &tty_tx_sem,
    .events = &tty_events,
};

static void test_close_open(void)
{
    int ret;

    ret = modem_backend_tty_init(&tty_backend, &tty_config);
    zassert_equal(ret, 0, "modem_backend_tty_init failed");

    ret = modem_backend_tty_start(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_start failed");

    ret = modem_backend_tty_stop(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_stop failed");

    ret = modem_backend_tty_deinit(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_deinit failed");
}

static void test_receive(void)
{
    int ret;
    char rx_buf[32];
    const char *test_data = "Hello Zephyr!";
    size_t test_data_len = strlen(test_data);

    ret = modem_backend_tty_init(&tty_backend, &tty_config);
    zassert_equal(ret, 0, "modem_backend_tty_init failed");

    ret = modem_backend_tty_start(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_start failed");

    /* Simulate incoming data */
    for (size_t i = 0; i < test_data_len; i++) {
        uint8_t *data_item = k_fifo_alloc_node(&mock_uart_rx_fifo);
        zassert_not_null(data_item, "Failed to allocate fifo node");
        *data_item = test_data[i];
        k_fifo_put(&mock_uart_rx_fifo, data_item);
    }

    /* Notify TTY backend about new data */
    modem_backend_tty_rx_data(&tty_backend, (uint8_t *)test_data, test_data_len);

    /* Wait for RX_RDY event and then read data */
    uint32_t events = k_event_wait(&tty_events, MODEM_BACKEND_TTY_EVT_RX_RDY, false, K_SECONDS(1));
    zassert_true((events & MODEM_BACKEND_TTY_EVT_RX_RDY) != 0, "RX_RDY event not raised");

    size_t bytes_read = modem_backend_tty_read(&tty_backend, rx_buf, sizeof(rx_buf));
    zassert_equal(bytes_read, test_data_len, "Incorrect bytes read");
    zassert_mem_equal(rx_buf, test_data, test_data_len, "Received data mismatch");

    ret = modem_backend_tty_stop(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_stop failed");

    ret = modem_backend_tty_deinit(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_deinit failed");
}

static void test_receive_ready_event_not_raised(void)
{
    int ret;
    uint32_t events;
    bool result;

    ret = modem_backend_tty_init(&tty_backend, &tty_config);
    zassert_equal(ret, 0, "modem_backend_tty_init failed");

    ret = modem_backend_tty_start(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_start failed");

    /* Do NOT simulate incoming data */

    /* Wait for RX_RDY event, it should NOT be raised */
    events = k_event_wait(&tty_events, MODEM_BACKEND_TTY_EVT_RX_RDY, false, K_SECONDS(1));

    result = (events & MODEM_BACKEND_TTY_EVT_RX_RDY) != 0;

    zassert_false(result, "RX_RDY event unexpectedly raised");

    ret = modem_backend_tty_stop(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_stop failed");

    ret = modem_backend_tty_deinit(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_deinit failed");
}

static void test_receive_ready_event_raised(void)
{
    int ret;
    uint32_t events;
    bool result;
    const char *test_data = "event_test";
    size_t test_data_len = strlen(test_data);

    ret = modem_backend_tty_init(&tty_backend, &tty_config);
    zassert_equal(ret, 0, "modem_backend_tty_init failed");

    ret = modem_backend_tty_start(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_start failed");

    /* Simulate incoming data */
    for (size_t i = 0; i < test_data_len; i++) {
        uint8_t *data_item = k_fifo_alloc_node(&mock_uart_rx_fifo);
        zassert_not_null(data_item, "Failed to allocate fifo node");
        *data_item = test_data[i];
        k_fifo_put(&mock_uart_rx_fifo, data_item);
    }

    /* Notify TTY backend about new data */
    modem_backend_tty_rx_data(&tty_backend, (uint8_t *)test_data, test_data_len);

    /* Wait for RX_RDY event */
    events = k_event_wait(&tty_events, MODEM_BACKEND_TTY_EVT_RX_RDY, false, K_SECONDS(2)); /* Increased timeout from K_SECONDS(1) to K_SECONDS(2) */

    result = (events & MODEM_BACKEND_TTY_EVT_RX_RDY) != 0;

    zassert_true(result, "RX_RDY event not raised");

    ret = modem_backend_tty_stop(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_stop failed");

    ret = modem_backend_tty_deinit(&tty_backend);
    zassert_equal(ret, 0, "modem_backend_tty_deinit failed");
}

static void before_each(void *fixture)
{
    ARG_UNUSED(fixture);
    /* Clear fifos and events before each test */
    while (k_fifo_get(&mock_uart_rx_fifo, K_NO_WAIT) != NULL) {
        /* empty */;
    }
    k_event_clear(&tty_events, 0xFFFFFFFF);
    k_sem_reset(&tty_tx_sem);
}

ZTEST_SUITE(modem_backend_tty_suite, NULL, NULL, before_each, NULL, NULL);

ZTEST_UNIT(modem_backend_tty_suite, test_close_open);
ZTEST_UNIT(modem_backend_tty_suite, test_receive);
ZTEST_UNIT(modem_backend_tty_suite, test_receive_ready_event_not_raised);
ZTEST_UNIT(modem_backend_tty_suite, test_receive_ready_event_raised);
